+    /**
+     * Calculates the space required for the domain axis/axes.
+     * 
+     * @param g2  the graphics device.
+     * @param plotArea  the plot area.
+     * @param space  a carrier for the result (<code>null</code> permitted).
+     * 
+     * @return The required space.
+     */
+    protected AxisSpace calculateDomainAxisSpace(Graphics2D g2, 
+                                                 Rectangle2D plotArea, 
+                                                 AxisSpace space) {
+                                                     
+        if (space == null) {
+            space = new AxisSpace();
+        }
+        
+        // reserve some space for the domain axis...
+        if (this.fixedDomainAxisSpace != null) {
+            if (this.orientation == PlotOrientation.HORIZONTAL) {
+                space.ensureAtLeast(
+                    this.fixedDomainAxisSpace.getLeft(), RectangleEdge.LEFT);
+                space.ensureAtLeast(this.fixedDomainAxisSpace.getRight(), 
+                        RectangleEdge.RIGHT);
+            }
+            else if (this.orientation == PlotOrientation.VERTICAL) {
+                space.ensureAtLeast(this.fixedDomainAxisSpace.getTop(), 
+                        RectangleEdge.TOP);
+                space.ensureAtLeast(this.fixedDomainAxisSpace.getBottom(), 
+                        RectangleEdge.BOTTOM);
+            }
+        }
+        else {
+            // reserve space for the primary domain axis...
+            RectangleEdge domainEdge = Plot.resolveDomainAxisLocation(
+                    getDomainAxisLocation(), this.orientation);
+            if (this.drawSharedDomainAxis) {
+                space = getDomainAxis().reserveSpace(g2, this, plotArea, 
+                        domainEdge, space);
+            }
+            
+            // reserve space for any domain axes...
+            for (int i = 0; i < this.domainAxes.size(); i++) {
+                Axis xAxis = (Axis) this.domainAxes.get(i);
+                if (xAxis != null) {
+                    RectangleEdge edge = getDomainAxisEdge(i);
+                    space = xAxis.reserveSpace(g2, this, plotArea, edge, space);
+                }
+            }
+        }
+
+        return space;
+                                                     
+    }
+    
+    /**
+     * Calculates the space required for the range axis/axes.
+     * 
+     * @param g2  the graphics device.
+     * @param plotArea  the plot area.
+     * @param space  a carrier for the result (<code>null</code> permitted).
+     * 
+     * @return The required space.
+     */
+    protected AxisSpace calculateRangeAxisSpace(Graphics2D g2, 
+                                                Rectangle2D plotArea, 
+                                                AxisSpace space) {
+                                                  
+        if (space == null) {
+            space = new AxisSpace(); 
+        }
+        
+        // reserve some space for the range axis...
+        if (this.fixedRangeAxisSpace != null) {
+            if (this.orientation == PlotOrientation.HORIZONTAL) {
+                space.ensureAtLeast(this.fixedRangeAxisSpace.getTop(), 
+                        RectangleEdge.TOP);
+                space.ensureAtLeast(this.fixedRangeAxisSpace.getBottom(), 
+                        RectangleEdge.BOTTOM);
+            }
+            else if (this.orientation == PlotOrientation.VERTICAL) {
+                space.ensureAtLeast(this.fixedRangeAxisSpace.getLeft(), 
+                        RectangleEdge.LEFT);
+                space.ensureAtLeast(this.fixedRangeAxisSpace.getRight(), 
+                        RectangleEdge.RIGHT);
+            }
+        }
+        else {
+            // reserve space for the range axes (if any)...
+            for (int i = 0; i < this.rangeAxes.size(); i++) {
+                Axis yAxis = (Axis) this.rangeAxes.get(i);
+                if (yAxis != null) {
+                    RectangleEdge edge = getRangeAxisEdge(i);
+                    space = yAxis.reserveSpace(g2, this, plotArea, edge, space);
+                }
+            }
+        }
+        return space;
+                                                    
+    }
+
+    /**
+     * Calculates the space required for the axes.
+     *
+     * @param g2  the graphics device.
+     * @param plotArea  the plot area.
+     *
+     * @return The space required for the axes.
+     */
+    protected AxisSpace calculateAxisSpace(Graphics2D g2, 
+                                           Rectangle2D plotArea) {
+        AxisSpace space = new AxisSpace();
+        space = calculateRangeAxisSpace(g2, plotArea, space);
+        space = calculateDomainAxisSpace(g2, plotArea, space);
+        return space;
+    }
